benchmark.reproducer_gdscript:
extends SceneTree
const Shell := preload("res://demo/burrow/modular_shell.gd")
const Footprint := preload("res://scripts/core/room_footprint.gd")
func _initialize() -> void:
	for side: int in [8, 16, 32, 64, 128]:
		var spec: Dictionary = make_spec(side)
		var samples: PackedInt64Array = PackedInt64Array()
		var cached: PackedInt64Array = PackedInt64Array()
		for iteration: int in range(5):
			var shell: Shell = Shell.new()
			var begin: int = Time.get_ticks_usec()
			var result: Dictionary = shell.rebuild(1, spec)
			samples.append(Time.get_ticks_usec() - begin)
			if not result.ok:
				push_error(String(result.error))
				quit(1)
				return
			begin = Time.get_ticks_usec()
			shell.rebuild(1, spec)
			cached.append(Time.get_ticks_usec() - begin)
		samples.sort()
		cached.sort()
		print("SHELL-BENCH cells=%d samples=5 build_median_usec=%d build_max_usec=%d cached_median_usec=%d" % [side*side,samples[2],samples[4],cached[2]])
	quit(0)
func make_spec(side: int) -> Dictionary:
	var cells: PackedInt32Array = Footprint.rectangle(0, 0, side, side, 16384).cells
	var floor_u: PackedInt32Array = PackedInt32Array()
	var ceiling_u: PackedInt32Array = PackedInt32Array()
	var state: PackedByteArray = PackedByteArray()
	floor_u.resize(side*side)
	ceiling_u.resize(side*side)
	ceiling_u.fill(2048)
	state.resize(side*side)
	state.fill(Shell.FINISHED)
	return {"cells":cells,"floor_u":floor_u,"ceiling_u":ceiling_u,"state":state,"origin_u":Vector2i.ZERO,
		"cell_size_u":1024,"minimum_headroom_u":1024,"openings":PackedInt32Array()}
